using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        // Collect all errors
        var errors = new List<(string Project, string Code, string Message, string File, int Line)>();
        var warnings = new List<(string Project, string Code, string Message, string File)>();
        var failedProjects = new HashSet<string>();

        build.VisitAllChildren<Error>(e => {
            var proj = GetParentProject(e);
            errors.Add((proj, e.Code ?? "", e.Message ?? e.Text ?? "", e.File ?? "", e.LineNumber));
        });

        build.VisitAllChildren<Warning>(w => {
            var proj = GetParentProject(w);
            warnings.Add((proj, w.Code ?? "", w.Message ?? w.Text ?? "", w.File ?? ""));
        });

        // Find projects that failed
        build.VisitAllChildren<Project>(p => {
            if (!p.Succeeded)
                failedProjects.Add(p.Name ?? "unknown");
        });

        Console.WriteLine("=== FAILED PROJECTS ===");
        foreach (var p in failedProjects.OrderBy(x => x))
            Console.WriteLine($"  - {p}");

        Console.WriteLine($"\n=== ALL ERRORS ({errors.Count}) ===");
        foreach (var group in errors.GroupBy(e => e.Project).OrderBy(g => g.Key))
        {
            Console.WriteLine($"\n--- Project: {group.Key} ---");
            foreach (var e in group)
            {
                Console.WriteLine($"  [{e.Code}] {e.File}({e.Line}): {e.Message}");
            }
        }

        if (warnings.Count > 0)
        {
            Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
            foreach (var group in warnings.GroupBy(w => w.Project).OrderBy(g => g.Key))
            {
                Console.WriteLine($"\n--- Project: {group.Key} ---");
                foreach (var w in group)
                    Console.WriteLine($"  [{w.Code}] {w.File}: {w.Message}");
            }
        }

        // Attempt to find project dependencies to identify cascading failures
        Console.WriteLine("\n=== PROJECT DEPENDENCY ANALYSIS ===");
        build.VisitAllChildren<Project>(p => {
            if (!p.Succeeded)
            {
                // Check if this project has references to other failed projects
                var hasRefToFailedProject = false;
                p.VisitAllChildren<Message>(m => {
                    if (m.Text != null)
                    {
                        foreach (var fp in failedProjects)
                        {
                            var fpBase = System.IO.Path.GetFileNameWithoutExtension(fp);
                            if (m.Text.Contains(fpBase) && (m.Text.Contains("ProjectReference") || m.Text.Contains("ResolveProjectReferences")))
                            {
                                hasRefToFailedProject = true;
                            }
                        }
                    }
                });

                // Check for MSB3202 or similar dependency errors
                var hasDependencyError = false;
                p.VisitAllChildren<Error>(e => {
                    if (e.Code == "MSB3202" || e.Code == "MSB4181" || 
                        (e.Message != null && e.Message.Contains("could not be resolved")))
                        hasDependencyError = true;
                });

                Console.WriteLine($"  {p.Name}: Succeeded={p.Succeeded}, HasRefToFailedProject={hasRefToFailedProject}, HasDependencyError={hasDependencyError}");
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
