using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        var errors = new List<(string Project, string Code, string Text, string File, int Line)>();
        var warnings = new List<(string Project, string Code, string Text, string File)>();
        var failedTargets = new HashSet<string>();

        build.VisitAllChildren<Error>(e => {
            var proj = GetParentProject(e);
            errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
        });

        build.VisitAllChildren<Warning>(w => {
            var proj = GetParentProject(w);
            warnings.Add((proj, w.Code ?? "", w.Text ?? "", w.File ?? ""));
        });

        // Find failed projects via Build node
        build.VisitAllChildren<Project>(p => {
            // Check children for error nodes
            bool hasErrors = false;
            p.VisitAllChildren<Error>(e => { hasErrors = true; });
            if (hasErrors)
                failedTargets.Add(p.Name ?? p.ToString());
        });

        Console.WriteLine("=== FAILED PROJECTS ===");
        foreach (var p in failedTargets.OrderBy(x => x))
            Console.WriteLine($"  - {p}");

        Console.WriteLine($"\n=== ALL ERRORS ({errors.Count}) ===");
        foreach (var group in errors.GroupBy(e => e.Project).OrderBy(g => g.Key))
        {
            Console.WriteLine($"\n--- Project: {group.Key} ---");
            foreach (var e in group)
            {
                Console.WriteLine($"  [{e.Code}] {e.File}({e.Line}): {e.Text}");
            }
        }

        if (warnings.Any(w => w.Code.StartsWith("CS") || w.Code.StartsWith("MSB") || w.Code.StartsWith("NU")))
        {
            Console.WriteLine($"\n=== RELEVANT WARNINGS ===");
            foreach (var group in warnings.Where(w => w.Code.StartsWith("CS") || w.Code.StartsWith("MSB") || w.Code.StartsWith("NU")).GroupBy(w => w.Project).OrderBy(g => g.Key))
            {
                Console.WriteLine($"\n--- Project: {group.Key} ---");
                foreach (var w in group)
                    Console.WriteLine($"  [{w.Code}] {w.File}: {w.Text}");
            }
        }
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
