using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main()
    {
        var build = BinaryLog.ReadBuild("build.binlog");

        // Get project references
        Console.WriteLine("=== PROJECT REFERENCES ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name == "Api.csproj" || p.Name == "Services.csproj" || p.Name == "Core.csproj")
            {
                bool printed = false;
                p.VisitAllChildren<AddItem>(item => {
                    if (item.Name == "ProjectReference" || item.Name == "PackageReference")
                    {
                        if (!printed) { Console.WriteLine($"\n{p.Name}:"); printed = true; }
                        foreach (var child in item.Children.OfType<Item>())
                            Console.WriteLine($"  {item.Name}: {child.Text}");
                    }
                });
            }
        });

        // Check if Api references Services
        Console.WriteLine("\n=== DEPENDENCY CHAIN (from messages) ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name == "Api.csproj")
            {
                p.VisitAllChildren<Message>(m => {
                    if (m.Text != null && (m.Text.Contains("Services") || m.Text.Contains("ProjectReference")))
                        Console.WriteLine($"  Api: {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
                });
            }
        });

        // Get the actual errors with full context  
        Console.WriteLine("\n=== ERROR DETAILS ===");
        build.VisitAllChildren<Error>(e => {
            Console.WriteLine($"  Code: {e.Code}");
            Console.WriteLine($"  File: {e.File}:{e.LineNumber}:{e.ColumnNumber}");
            Console.WriteLine($"  Text: {e.Text}");
            Console.WriteLine($"  Project: {GetParentProject(e)}");
            Console.WriteLine();
        });

        // Check for Api failures (cascading?)
        Console.WriteLine("=== API PROJECT STATUS ===");
        bool apiHasErrors = false;
        build.VisitAllChildren<Project>(p => {
            if (p.Name == "Api.csproj")
            {
                p.VisitAllChildren<Error>(e => { apiHasErrors = true; });
            }
        });
        Console.WriteLine($"  Api.csproj has errors: {apiHasErrors}");
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
