using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main()
    {
        var build = BinaryLog.ReadBuild("build.binlog");

        // Dump the Services.csproj content from the binlog
        Console.WriteLine("=== Services.csproj ITEMS ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name != "Services.csproj") return;

            // Check AddItem for PackageReference
            p.VisitAllChildren<NamedNode>(n => {
                if (n.Name != null && n.Name.Contains("Package"))
                    Console.WriteLine($"  NamedNode: {n.GetType().Name} Name={n.Name} Children={n.Children?.Count}");
            });

            // Look at all messages about packages
            p.VisitAllChildren<Message>(m => {
                if (m.Text != null && (m.Text.Contains("PackageReference") || m.Text.Contains("Newtonsoft") || m.Text.Contains("package")))
                    Console.WriteLine($"  Msg: {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
            });
        });

        // Try to find the project file content from the evaluation
        Console.WriteLine("\n=== PROJECT FILE ITEMS (all projects) ===");
        build.VisitAllChildren<Project>(p => {
            p.VisitAllChildren<AddItem>(ai => {
                if (ai.Name == "PackageReference")
                {
                    Console.Write($"  {p.Name} PackageReference: ");
                    foreach (var c in ai.Children.OfType<Item>())
                        Console.Write($"{c.Text} ");
                    Console.WriteLine();
                }
            });
        });

        // Check if there's an ItemGroup with references
        Console.WriteLine("\n=== RESOLVED REFERENCES ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name != "Services.csproj") return;
            p.VisitAllChildren<AddItem>(ai => {
                if (ai.Name == "Reference" || ai.Name == "_ResolvedProjectReferencePaths")
                {
                    foreach (var c in ai.Children.OfType<Item>())
                        Console.WriteLine($"  {ai.Name}: {c.Text}");
                }
            });
        });
    }
}
