class Program
{
    static void Main()
    {
        var build = BinaryLog.ReadBuild("build.binlog");

        // The SourceFilesArchive is a byte[] containing a zip
        var archive = build.SourceFilesArchive;
        if (archive != null && archive.Length > 0)
        {
            Console.WriteLine($"Archive size: {archive.Length} bytes");
            using var ms = new MemoryStream(archive);
            using var zip = new ZipArchive(ms, ZipArchiveMode.Read);
            foreach (var entry in zip.Entries)
            {
                if (entry.FullName.EndsWith(".csproj") || entry.FullName.Contains("UserService"))
                {
                    Console.WriteLine($"\n--- {entry.FullName} ---");
                    using var reader = new StreamReader(entry.Open());
                    Console.WriteLine(reader.ReadToEnd());
                }
            }
        }
        else
        {
            Console.WriteLine("No source files archive");
        }
    }
}
